#include "yukari/vm.hpp"
#include "yukari/save.hpp"
#include <cassert>
#include <iostream>
using namespace yukari;
int main(){Script getter;getter.max_locals=1;getter.elements={{10,0,0,0,"",0},{0,0,0,0,"NowScriptStateGet",0},{0,0,0,0,"Observe",0}};getter.instructions={{0,0,{}},{1,1,{}},{3,2,{0}}};Vm query([&](const std::string&){return getter;});int observed=0;query.set_host([&](const HostCall& c)->std::optional<HostResult>{assert(c.function=="Observe");observed=std::get<int32_t>(c.arguments.at(0));return HostResult{};});query.start("query");query.set_script_state(47);assert(query.run()==VmStatus::Halted&&observed==47);Script s;s.elements={{0,0,0,0,"NowScriptStateGet",0},{0,0,0,0,"Pause",0}};s.instructions={{0,0,{}},{2,1,{}}};Vm vm([&](const std::string&){return s;});vm.set_host([](const HostCall&)->std::optional<HostResult>{return HostResult{true};});assert(vm.script_state()==0);vm.start("main");vm.set_script_state(1);assert(vm.run()==VmStatus::Waiting);auto native=vm.export_original();auto saved=vm.snapshot();vm.set_script_state(17);vm.restore(saved);assert(vm.script_state()==1);vm.set_script_state(-4);vm.import_original(native);assert(vm.script_state()==-4);vm.reset("main");assert(vm.script_state()==-4);assert(vm.run()==VmStatus::Waiting);vm.resume();assert(vm.run()==VmStatus::Halted);vm.start("again");assert(vm.script_state()==-4);std::cout<<"sticky script state intrinsic, snapshot, reset and native slot preservation passed\n";}
